export interface AdminDeviceRecord {
  id: string;
  k: number;
  farmer: string;
  business: string;
  phone: string;
  village: string;
  district: string;
  state: string;
  lat: number;
  lon: number;
  pond: string;
  site: string;
  model: string;
  capacity: string;
  serial: string;
  installed: Date;
  wEnd: Date;
  wDays: number;
  amc: 'warranty' | 'active' | 'none';
  amcEnd: string;
  idle: number;
  complaint: string | null;
  status: 'running' | 'standby' | 'maint' | 'critical';
  hours: number;
  hasDO: boolean;
  hasTemp: boolean;
  mode: string;
  fw: string;
  tech: string;
  installer: string;
  doNow: string | null;
  svc: Array<{
    dt: Date;
    title: string;
    type: 'Install' | 'Cleaning' | 'Calibration' | 'Update' | 'Fault';
    by: string;
    note: string;
  }>;
  rawTelemetry?: DeviceTelemetry;
}

export interface AdminComplaintRecord {
  id: string;
  device: string;
  issue: string;
  priority: 'High' | 'Medium' | 'Low';
  source: string;
  age: string;
  stage: number; // 0=New, 1=Assigned, 2=Working, 3=Done
  farmer: string;
  place: string;
  tech: string;
  phone?: string;
  messages?: any[];
  createdAt?: string;
}

export interface AdminJobRecord {
  id: string;
  device: string;
  job: string;
  why: string;
  tech: string;
  prog: number; // 0=Next, 1=On site, 2=Done
}

