export const ADMIN_MODELS_SEED = [
  ['MNB-1', '1 HP · ponds up to 0.75 acre'],
  ['MNB-2', '2 HP · ponds up to 1.5 acres'],
  ['MNB-3', '3 HP · ponds up to 2.5 acres']
] as const;

export const ADMIN_TECHS_SEED = ['Suresh', 'Ravi', 'Kiran'] as const;

export const ADMIN_TECH_BY_DISTRICT: Record<string, string> = {
  'West Godavari': 'Suresh',
  'Konaseema': 'Ravi',
  'Kakinada': 'Ravi',
  'Nellore': 'Kiran',
  'Balasore': 'Kiran'
};

const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
export function fmtDate(d: Date): string {
  return `${d.getDate()} ${MON[d.getMonth()]} ${d.getFullYear()}`;
}

export function addMonths(d: Date, m: number): Date {
  const x = new Date(d.getTime());
  x.setMonth(x.getMonth() + m);
  return x;
}

// Generate the realistic fleet of devices for Oxynity Smart Admin
export function generateAdminFleet(): AdminDeviceRecord[] {
  const today = new Date(2026, 9, 18);
  const idleP = [0, 4, 0, 1, 0, 0, 0, 9, 0, 5, 0, 0, 2, 0, 12, 0, 0, 3, 0, 0, 1, 0, 0];
  const complaintAt: Record<number, string> = { 10: 'Low bubble output', 21: 'Water leak at mixer' };
  const out: AdminDeviceRecord[] = [];
  let k = 0;

  ADMIN_FARMS_SEED.forEach((f) => {
    let pondNo = 0;
    const sites = f[2];
    sites.forEach((s) => {
      const [village, district, state, baseLat, baseLon, pondCount] = s;
      for (let j = 0; j < (pondCount as number); j++) {
        pondNo++;
        const months = 5 + ((k * 5) % 31);
        const inst = new Date(2026, 9 - months, 1 + ((k * 7) % 27));
        const wEnd = addMonths(inst, 24);
        const wDays = Math.round((wEnd.getTime() - today.getTime()) / 86400000);
        const idle = k === 7 ? 9 : idleP[k % idleP.length];
        const complaint = complaintAt[k] || null;
        const status: 'running' | 'standby' | 'maint' | 'critical' =
          complaint || idle > 7
            ? 'critical'
            : idle >= 3
            ? 'maint'
            : idle >= 1
            ? 'standby'
            : 'running';
        const hours = Math.round(months * 30 * 11.5 + k * 37);
        const hasDO = k % 3 !== 0;
        const hasTemp = k % 4 === 1;
        const m = ADMIN_MODELS_SEED[k % 3];
        const id = `OXY-${String(101 + k).padStart(4, '0')}`;
        const tech = ADMIN_TECH_BY_DISTRICT[district as string] || ADMIN_TECHS_SEED[k % 3];
        
        const svc: AdminDeviceRecord['svc'] = [
          {
            dt: inst,
            title: 'Installed & commissioned',
            type: 'Install',
            by: `${ADMIN_TECHS_SEED[(k + 2) % 3]}${hasDO ? ' · with DO sensor' : ' · manual mode'}`,
            note: ''
          }
        ];

        const cleanings = Math.floor(hours / 2000);
        const perClean = months / Math.max(1, hours / 2000);
        for (let c = 1; c <= cleanings; c++) {
          svc.push({
            dt: addMonths(inst, Math.round(c * perClean)),
            title: 'Ultrasonic mixer cleaning',
            type: 'Cleaning',
            by: tech,
            note: `${Number(c * 2000).toLocaleString('en-IN')} run-hour service`
          });
        }
        if (hasDO) {
          svc.push({
            dt: new Date(2026, 8, 2 + (k % 20)),
            title: 'DO sensor calibrated',
            type: 'Calibration',
            by: tech,
            note: ''
          });
        }
        if (months > 6) {
          svc.push({
            dt: new Date(2026, 9, 2),
            title: 'Firmware updated to v2.4.1',
            type: 'Update',
            by: 'Remote · Admin',
            note: ''
          });
        }
        if (k === 7) {
          svc.push({
            dt: new Date(2026, 9, 9),
            title: 'Motor tripped — generator stopped',
            type: 'Fault',
            by: 'Controller alarm',
            note: 'Technician on site 18 Oct, checking motor contactor'
          });
        }
        if (complaint) {
          svc.push({
            dt: new Date(2026, 9, 15),
            title: `Complaint: ${complaint}`,
            type: 'Fault',
            by: 'Farmer app',
            note: `Assigned to ${tech}`
          });
        }
        svc.sort((a, b) => b.dt.getTime() - a.dt.getTime());

        out.push({
          id,
          k,
          farmer: f[0] as string,
          business: f[1] as string,
          phone: '+91 98480 ' + (30000 + k * 123),
          village: village as string,
          district: district as string,
          state: state as string,
          lat: (baseLat as number) + (j % 2) * 0.02,
          lon: (baseLon as number) + j * 0.025,
          pond: `Pond ${pondNo}`,
          site: `${village} · ${district}`,
          model: m[0],
          capacity: m[1],
          serial: `${m[0]}-${months > 18 ? 23 : 24}-${4100 + k * 13}`,
          installed: inst,
          wEnd,
          wDays,
          amc: wDays < 0 ? (k % 2 === 0 ? 'active' : 'none') : 'warranty',
          amcEnd: fmtDate(addMonths(wEnd, 12)),
          idle,
          complaint,
          status,
          hours,
          hasDO,
          hasTemp,
          mode: hasDO ? 'Auto (DO 5 → 9 ppm)' : 'Manual',
          fw: 'v2.4.1',
          tech,
          installer: ADMIN_TECHS_SEED[(k + 2) % 3],
          doNow: hasDO ? ((status === 'running' ? 5.2 + (k % 6) * 0.6 : 6 + (k % 4) * 0.4)).toFixed(1) : null,
          svc
        });
        k++;
      }
    });
  });

  return out;
}

export function generateAdminComplaints(fleet: AdminDeviceRecord[]): AdminComplaintRecord[] {
  if (!fleet || fleet.length === 0) return [];
  const seeds = [
    ['CMP-1048', 'OXY-0113', 'DO reading stuck at 0.0', 'Medium', 'Farmer app', '40 min', 0],
    ['CMP-1047', 'OXY-0122', 'Water leak at mixer', 'High', 'Phone call', '2 h', 0],
    ['CMP-1046', 'OXY-0111', 'Low bubble output', 'Medium', 'Farmer app', '5 h', 1],
    ['CMP-1044', 'OXY-0108', 'Generator not starting since 9 Oct', 'High', 'Auto alarm', '9 d', 2],
    ['CMP-1043', 'OXY-0118', 'Pump noise', 'Medium', 'Phone call', '2 d', 2],
    ['CMP-1039', 'OXY-0105', 'App not showing run hours', 'Low', 'Farmer app', '2 d', 3],
    ['CMP-1036', 'OXY-0101', 'Bubbles weak after cleaning', 'Medium', 'Phone call', '3 d', 3]
  ] as const;

  return seeds.map((s) => {
    const d = fleet.find((x) => x.id === s[1]) || fleet[0];
    return {
      id: s[0],
      device: d?.id || s[1],
      issue: s[2],
      priority: s[3] as 'High' | 'Medium' | 'Low',
      source: s[4],
      age: s[5],
      stage: s[6],
      farmer: d?.farmer || 'Farmer Operator',
      place: d ? `${d.village || 'Coastal Basin'}, ${d.district || 'West Godavari'}` : 'Aquaculture Facility',
      tech: s[6] === 0 ? 'Unassigned' : d?.tech || 'Field Tech'
    };
  });
}

export function generateAdminJobs(fleet: AdminDeviceRecord[]): AdminJobRecord[] {
  if (!fleet || fleet.length === 0) return [];
  const jobs: AdminJobRecord[] = [];
  const sorted = fleet.slice().sort((a, b) => b.idle - a.idle);

  sorted.forEach((d) => {
    if (!d) return;
    if (d.status === 'critical') {
      jobs.push({
        id: 'J' + d.id,
        device: d.id,
        job: d.complaint ? `Repair · ${d.complaint.toLowerCase()}` : `Repair · not running ${d.idle} days`,
        why: d.complaint ? `Complaint noted: ${d.complaint}` : `Off for ${d.idle} days`,
        tech: d.tech || 'Field Tech',
        prog: d.k === 7 ? 1 : 0
      });
    } else if (d.status === 'maint') {
      jobs.push({
        id: 'J' + d.id,
        device: d.id,
        job: 'Maintenance check',
        why: `Off for ${d.idle} days`,
        tech: d.tech || 'Field Tech',
        prog: 0
      });
    }
  });

  fleet.forEach((d) => {
    if (!d) return;
    if (d.hasDO && d.k % 5 === 2) {
      jobs.push({
        id: 'C' + d.id,
        device: d.id,
        job: 'DO sensor calibration',
        why: 'Sensor 45+ days since calibration',
        tech: d.tech || 'Field Tech',
        prog: d.k % 2
      });
    }
  });

  return jobs;
}

// CSV generation utilities
export function toCsv(rows: (string | number)[][]): string {
  return rows
    .map((r) =>
      r
        .map((v) => {
          const s = String(v ?? '');
          return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
        })
        .join(',')
    )
    .join('\r\n');
}

export function saveCsvFile(filename: string, content: string): void {
  exportFile({
    filename,
    content: '\ufeff' + content,
    mimeType: 'text/csv;charset=utf-8;',
    title: filename,
    dialogTitle: 'Export / Save CSV Report',
  }).catch((e) => {
    console.error('Failed to export CSV:', e);
  });
}

// Helper to convert any real DeviceTelemetry into an AdminDeviceRecord
export function telemetryToAdminRecord(
  dev: DeviceTelemetry,
  idx: number = 0
): AdminDeviceRecord {
  const isRunning = dev.status === 'ON';
  const isCritical =
    dev.status === 'ERROR' ||
    (dev.doSensorEnabled !== false && dev.doLevel >= 0 && dev.doLevel < (dev.minDoAlert || 5.0));
  const isMaint =
    dev.status === 'MAINTENANCE' ||
    (dev.totalRunHours || 0) >=
      (dev.lastMaintenanceHours || 0) + (dev.maintenanceIntervalHours || 500);

  let adminStatus: 'running' | 'standby' | 'maint' | 'critical' = 'standby';
  if (isCritical) adminStatus = 'critical';
  else if (isMaint) adminStatus = 'maint';
  else if (isRunning) adminStatus = 'running';
  else adminStatus = 'standby';

  const installedDate = new Date(2025, 3, 10 + (idx % 20));
  const wEndDate = new Date(2027, 3, 10 + (idx % 20));
  const diffDays = Math.max(
    0,
    Math.round((wEndDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24))
  );

  const locParts = (dev.locationName || '').split(',').map((s) => s.trim());
  const village = locParts[0] || 'Coastal Basin';
  const district = locParts[1] || 'West Godavari';
  const state = locParts[2] || 'Andhra Pradesh';

  const farmerName =
    dev.contactPerson?.name ||
    dev.ownerEmail?.split('@')[0] ||
    `Farmer (${dev.deviceId})`;
  const business =
    dev.contactPerson?.facilityName || dev.name || 'Oxynity Aquaculture Farm';

  return {
    id: dev.deviceId,
    k: idx,
    farmer: farmerName,
    business,
    phone: dev.contactPerson?.phone || '+91 98480 34211',
    village,
    district,
    state,
    lat: dev.calibratedLatitude || dev.latitude || 16.54,
    lon: dev.calibratedLongitude || dev.longitude || 81.52,
    pond: dev.name || `Pond ${dev.deviceId}`,
    site: dev.locationName || `${village} · ${district}`,
    model: 'MNBG-2.0',
    capacity: '2 HP · Micro-Nano Bubble Aerator',
    serial: `MNBG-24-${dev.deviceId.replace(/[^0-9]/g, '') || '1001'}`,
    installed: installedDate,
    wEnd: wEndDate,
    wDays: diffDays,
    amc: diffDays > 0 ? 'warranty' : 'active',
    amcEnd: fmtDate(wEndDate),
    idle: isRunning ? 0 : 1,
    complaint: isCritical ? 'Low DO Hypoxia Warning' : null,
    status: adminStatus,
    hours: Math.round(dev.totalRunHours || 0),
    hasDO: dev.doSensorEnabled !== false,
    hasTemp: dev.waterTemp !== undefined,
    mode: dev.autoMode
      ? `Auto (DO ${dev.minDoAlert || 5.0} → ${dev.maxDoAlert || 9.0} ppm)`
      : 'Manual (MNBG)',
    fw: dev.firmwareVersion || 'v2.4.1',
    tech: 'Suresh Varma',
    installer: 'Oxynity Field Tech',
    doNow: dev.doLevel >= 0 ? dev.doLevel.toFixed(1) : null,
    svc: [
      {
        dt: installedDate,
        title: 'Factory Commissioning & Optical Calibration',
        type: 'Install',
        by: 'Oxynity Engineering',
        note: 'Optical DO sensor & 2G cellular telemetry online',
      },
    ],
    rawTelemetry: dev,
  };
}
